// th15_s3_b3 — TH15 v1.00b Stage 3 Boss2 (3rd nonspell).
// Source: st03bs.ecl.txt Boss2 (226-296) + Boss2_at (298-409); entry state from Boss (8-34).

const TH15_BIG_BALL2: int = 656;  // source type 19 (etSprite(0, 19, 2))
const TH15_PELLET2: int = 368;    // source type 1  (etSprite(1, 1, 4))

const TIME_LIMIT: int = 2644;     // 120 opening buffer + 2520 source window + 4 entry cleanup
const OPENING_BUFFER: int = 120;

// ---------------------------------------------------------------- moveRand
// Source Boss2: moveRand(60, 4, 1.0) with moveLimit(0, 128, 280, 96).
// Recipe: signed-unit*pi direction, linear speed 1-k/60, clamp x[-140,140] y[80,176];
// inner direction thresholds are a quarter of the limit size (x +-70, y 104..152).
sub boss_arm_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub boss_begin_move(a: int) {
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    boss_arm_step();
}

sub boss_move_rand() {
    // Source 412 handler: R = pi * signed unit random.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    boss_begin_move(a);
    for i in 0..60 {
        wait(1);
        boss_arm_step();
    }
}

// ---------------------------------------------------------------- Boss2_at
// One volley of the source ring: etAngle(a, 1.0) with etCount(n,1) => base + i*2pi/n.
// etOffsetRad(off, 64) places the muzzle; EX type 2 (ANIM a=1) keeps the entry
// displacement position -= 4*velocity, which is folded into the spawn point here.
sub boss_fire_volley(shape: int, color: int, n: int, base: int, off: int, sp: fx) {
    var ox: fx = 64fx * cos(off as angle);
    var oy: fx = 64fx * sin(off as angle);
    var back: fx = 4fx * sp;
    for i in 0..n {
        var a: int = base + (i * 65536) / n;
        _ = fire(shape, color,
                 $self_x + ox - back * cos(a as angle),
                 $self_y + oy - back * sin(a as angle),
                 sp, a as angle, none, none);
    }
}

// One synchronous Boss2_at call. C (%C) is floatTime(1,%C,200,0,start,goal):
// linear ramp over 200 frames from start to goal, sampled at each etSpeed.
sub boss_burst(a: int, b: int, rounds: int, w1: int, w2: int, n0: int, n1: int,
               sp_start: fx, sp_goal: fx) {
    var f2: int = a;
    var off: int = rand(65536) - 32768;   // source %E = RANDRAD
    var d: int = 0;
    var t: int = 0;
    for k in 0..rounds {
        // source also samples RANDF2*208 / RANDF*192-16 into F0/F1 here; no consumer.
        var sp: fx = sp_start;
        if t < 200 { sp = sp_start + (sp_goal - sp_start) * (t as fx) / 200fx; }
        else { sp = sp_goal; }
        boss_fire_volley(TH15_BIG_BALL2, 2, n0, f2, off, sp);

        wait(w1);
        t = t + w1;
        f2 = f2 + b;
        if global(GVAR_RANK) >= RANK_NORMAL && (d % 2) == 0 {
            var sp1: fx = sp_start;
            if t < 200 { sp1 = sp_start + (sp_goal - sp_start) * (t as fx) / 200fx; }
            else { sp1 = sp_goal; }
            boss_fire_volley(TH15_PELLET2, 4, n1, f2, -off, sp1 * 0.5fx);
        }
        f2 = f2 + b;
        off = off - 20252;                // source %E = %E - 1.941611 rad
        wait(w2);
        t = t + w2;
        d = d + 1;
    }
}

// Source entry: setInvuln(120), lifeSet(19100), 4-frame cleanup before timerReset,
// then 60+60 frames of intro before Boss2_1156. Boss2_at wall sequence:
// burst; wait(20); moveRand(60); wait(60); burst; wait(20); moveRand(60); wait(60); loop.
async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);    // source setHitbox(48,48): circle radius 48/2
    set_hurtbox(20fx);   // source setHurtbox(40,40): circle radius 40/2
    set_self_int(0, 60); // no moveRand armed yet => zero movement
    set_self_fx(0, 1fx);
    set_self_fx(1, 0fx);
    wait(2);             // source +2 (chapter/UI cleanup omitted)
    wait(2);             // source +2 before timerReset
    wait(60);            // source intro wait(60)
    wait(60);            // source intro wait(60)

    var rank: int = global(GVAR_RANK);
    var b1: int = 182;
    var rounds: int = 200;
    var w1: int = 1;
    var w2: int = 1;
    var n1: int = 2;
    var s0: fx = 1fx;
    var s1: fx = 3fx;
    if rank == RANK_EASY {
        b1 = 364;                    // 0.034907 rad
        rounds = 100;
        w1 = 2;
        w2 = 2;
    }
    if rank == RANK_HARD { n1 = 5; }
    if rank == RANK_LUNATIC {
        w2 = 0;                      // second wait is 0 on Lunatic
        s0 = 3fx;                    // floatTime start
        s1 = 4fx;                    // floatTime goal
    }
    loop {
        boss_burst(32768, b1, rounds, w1, w2, 2, n1, s0, s1);  // A=pi, B=+1deg(E:2deg)
        wait(20);
        boss_move_rand();
        boss_burst(0, -182, rounds, w1, w2, 2, n1, s0, s1);    // A=0, B=-1deg
        wait(20);
        boss_move_rand();
    }
}

// ---------------------------------------------------------------- shell
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 19100, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
